import os
import platform
import argparse
from pathlib import Path

def get_target_directories(test_dir=None):
    """Determine target directories for scanning (system temp or test dir)."""
    if test_dir:
        return [Path(test_dir)]

    if platform.system() == "Windows":
        return [Path(os.environ["TEMP"]), Path(os.environ["USERPROFILE"]) / "AppData" / "Local" / "Temp"]
    else:  # Linux/macOS
        return [Path("/tmp"), Path("/var/log"), Path.home() / ".cache"]

def is_critical_directory(path):
    """Check if a directory is system-critical (to avoid)."""
    critical = {
        "Windows": {
            Path("C:\\Windows\\System32"),
            Path("C:\\Windows\\System"),
            Path("C:\\Program Files"),
            Path("C:\\Users\\Public")
        },
        "Linux": {
            Path("/proc"),
            Path("/sys"),
            Path("/dev"),
            Path("/root"),
            Path("/boot")
        },
        "Darwin": {  # macOS
            Path("/System"),
            Path("/Library"),
            Path("/Volumes")
        }
    }
    return path in critical.get(platform.system(), set())

def get_insignificant_extensions():
    """Return file extensions considered 'insignificant'."""
    return {".tmp", ".log", ".old", ".bak", ".cache", ".swp", ".tmp.bak", ".log.1"}

def scan_files(target_dirs):
    """Scan target directories for insignificant files (excluding critical dirs)."""
    insignificant_files = []
    extensions = get_insignificant_extensions()

    for dir in target_dirs:
        if not dir.exists():
            print(f"Warning: Directory {dir} does not exist. Skipping.")
            continue

        if is_critical_directory(dir):
            print(f"Warning: Skipping critical directory {dir}.")
            continue

        for root, _, files in os.walk(dir):
            current_dir = Path(root)
            if is_critical_directory(current_dir):
                print(f"Warning: Skipping critical subdirectory {current_dir}.")
                continue  # Skip subdirs if parent is critical

